<?php if($pages>1): ?><nav class="event-pagination" aria-label="Halaman kegiatan"><?php if($page>1): ?><a href="<?= $base.'?page='.($page-1) ?>" aria-label="Halaman sebelumnya">←</a><?php endif; ?><?php if($page>3): ?><a href="<?= $base.'?page=1' ?>">1</a><?php if($page>4): ?><span aria-hidden="true">…</span><?php endif; ?><?php endif; ?><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++): ?><a class="<?= $n===$page?'active':'' ?>" href="<?= $base.'?page='.$n ?>" <?= $n===$page?'aria-current="page"':'' ?>><?= $n ?></a><?php endfor; ?><?php if($page<$pages-2): ?><?php if($page<$pages-3): ?><span aria-hidden="true">…</span><?php endif; ?><a href="<?= $base.'?page='.$pages ?>"><?= $pages ?></a><?php endif; ?><?php if($page<$pages): ?><a href="<?= $base.'?page='.($page+1) ?>" aria-label="Halaman berikutnya">→</a><?php endif; ?></nav><?php endif; ?>
